    10→	forkchoicetypes "github.com/OffchainLabs/prysm/v6/beacon-chain/forkchoice/types"
    11→	"github.com/OffchainLabs/prysm/v6/beacon-chain/state"
    12→	fieldparams "github.com/OffchainLabs/prysm/v6/config/fieldparams"
    13→	"github.com/OffchainLabs/prysm/v6/config/params"
    14→	"github.com/OffchainLabs/prysm/v6/consensus-types/blocks"
    15→	"github.com/OffchainLabs/prysm/v6/consensus-types/primitives"
    16→	"github.com/OffchainLabs/prysm/v6/encoding/bytesutil"
